### Implementation

```typescript
/**
 * Debounces a function so that it will only be executed after the specified
 * delay has passed since the last time it was called.
 * 
 * @param fn - The function to debounce.
 * @param ms - The delay in milliseconds.
 * @returns A new debounced function.
 */
function debounce<T extends (...args: any[]) => void>(
  fn: T,
  ms: number
): (...args: Parameters<T>) => void {
  let timeoutId: ReturnType<typeof setTimeout> | null = null;

  return function (this: any, ...args: Parameters<T>) {
    // Clear the existing timeout if one exists
    if (timeoutId !== null) {
      clearTimeout(timeoutId);
    }

    // Set a new timeout
    timeoutId = setTimeout(() => {
      // Execute the original function with the captured arguments
      fn.apply(this, args);
    }, ms);
  };
}

export { debounce };
